<script setup lang="ts">
import {ref,onMounted} from 'vue';import {admin,money,date} from '../../../shared/api';import type {Dashboard} from '../../../shared/adminTypes';import type {Page,Order} from '../../../shared/types';import {useLoad} from '../../../shared/useLoad'
const data=ref<Dashboard>(),orders=ref<Order[]>([]),{loading,error,run}=useLoad();const load=()=>run(async()=>{const [d,o]=await Promise.all([admin<Dashboard>('GET','/admin/dashboard'),admin<Page<Order>>('GET','/admin/orders',undefined,{status:'paid',pageSize:5})]);data.value=d;orders.value=o.items});onMounted(load)
</script>
<template><p class="eyebrow">HELLO, STORE OWNER</p><h2>每一份托付，认真照顾。</h2><p>今天有 {{data?.pendingTasks.pickupCount||0}} 笔待自提订单、{{data?.pendingTasks.afterSaleReviewCount||0}} 笔售后待审核。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-skeleton v-if="loading&&!data" animated :rows="5"/><template v-if="data"><div class="metrics"><article v-for="item in [['今日收款',money(data.grossSalesAmount),'按支付成功时间统计'],['今日订单',data.createdOrderCount,`${data.paidOrderCount} 笔已支付`],['在售宠物',data.onSalePetCount,'当前可售个体'],['AI 会话',data.aiSessionCount,'今日有提问的会话']]" :key="item[0]" class="metric"><p>{{item[0]}}</p><strong>{{item[1]}}</strong><small>{{item[2]}}</small></article></div><div class="toolbar"><el-button type="primary" size="large" @click="$router.push('/orders?pickup=1')">办理到店核销</el-button><el-button size="large" @click="$router.push('/pets/new')">发布宠物</el-button><el-button size="large" @click="$router.push('/after-sales')">处理售后</el-button><el-button text :loading="loading" @click="load">刷新</el-button></div><h3>待处理订单</h3><div class="table-panel"><el-table :data="orders" empty-text="当前没有待自提订单"><el-table-column label="订单 / 宠物" min-width="240"><template #default="{row}">{{row.orderNo}} · {{row.product.name}}</template></el-table-column><el-table-column prop="contactName" label="联系人" min-width="120"/><el-table-column label="实付" min-width="120"><template #default="{row}">{{money(row.amount)}}</template></el-table-column><el-table-column prop="statusText" label="状态" min-width="110"/><el-table-column label="操作" width="130"><template #default><el-button link type="primary" @click="$router.push('/orders?pickup=1')">办理核销</el-button></template></el-table-column></el-table></div><p class="small muted" style="margin-top:20px">更新时间 {{date(data.updatedAt)}}</p></template></template>
